<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/safety_vote_engagement.php';

function sveng_gate():void{$required=['SafetyVote_Promotions','SafetyVote_NotificationReads'];$marks=implode(',',array_fill(0,count($required),'?'));$found=db_rows("SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ($marks)",$required);if(count($found)!==2)json_response(['success'=>false,'code'=>'SAFETY_VOTE_ENGAGEMENT_SETUP_REQUIRED','message'=>'Safety Vote engagement migration is required.'],503);$setting=db_row("SELECT SettingValue FROM SafetyVote_Settings WHERE SettingKey='engagement_enabled'");if(($setting['SettingValue']??'0')!=='1')json_response(['success'=>false,'code'=>'SAFETY_VOTE_ENGAGEMENT_DISABLED','message'=>'Safety Vote engagement features are disabled.'],503);}
function sveng_row(int$id,bool$lock=false):?array{return db_row("SELECT p.*,c.CampaignCode,c.CurrentVersionID,c.Status CampaignStatus,v.TitleTh CampaignTitle,v.CampaignType FROM SafetyVote_Promotions p JOIN SafetyVote_Campaigns c ON c.id=p.CampaignID JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE p.id=?".($lock?' FOR UPDATE':''),[$id]);}
function sveng_public(array$r):array{return['id'=>(int)$r['id'],'campaignId'=>(int)$r['CampaignID'],'campaignCode'=>$r['CampaignCode'],'campaignTitle'=>$r['CampaignTitle'],'campaignStatus'=>$r['CampaignStatus'],'titleTh'=>$r['TitleTh'],'subtitleTh'=>$r['SubtitleTh'],'ctaLabel'=>$r['CtaLabel'],'desktopFileId'=>!empty($r['DesktopFileID'])?(int)$r['DesktopFileID']:null,'mobileFileId'=>!empty($r['MobileFileID'])?(int)$r['MobileFileID']:null,'altText'=>$r['AltText'],'priority'=>(int)$r['Priority'],'startAt'=>$r['StartAt'],'endAt'=>$r['EndAt'],'status'=>$r['Status'],'rowVersion'=>(int)$r['RowVersion']];}
function sveng_remove_file(?string$name):void{if(!$name)return;$file=sv_private_dir().DIRECTORY_SEPARATOR.basename($name);if(is_file($file))@unlink($file);}

function handle_safety_vote_engagement_routes(string$method,string$path):bool{
 $adminCenter=$path==='/safety-vote/admin/engagement/action-center';$adminList=$path==='/safety-vote/admin/promotions';$adminItem=route_params($path,'/safety-vote/admin/promotions/:id');$asset=route_params($path,'/safety-vote/admin/promotions/:id/assets/:slot');$promotions=$path==='/safety-vote/me/promotions';$center=$path==='/safety-vote/notification-center';$read=route_params($path,'/safety-vote/notification-center/:id/read');$readAll=$path==='/safety-vote/notification-center/read-all';
 if(!$adminCenter&&!$adminList&&!$adminItem&&!$asset&&!$promotions&&!$center&&!$read&&!$readAll)return false;$u=require_user();sveng_gate();
 if($adminCenter&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$tasks=[];$drafts=db_rows("SELECT c.id,c.CampaignCode,v.TitleTh,(SELECT COUNT(*) FROM SafetyVote_Questions q WHERE q.CampaignVersionID=c.CurrentVersionID AND q.Status='Active') questionCount,(SELECT COUNT(*) FROM SafetyVote_EligibilityRules er WHERE er.CampaignVersionID=c.CurrentVersionID AND er.IsActive=1) ruleCount FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.Status='Draft' ORDER BY c.UpdatedAt DESC LIMIT 20");foreach($drafts as$r)if(!(int)$r['questionCount']||!(int)$r['ruleCount'])$tasks[]=['key'=>'draft-readiness','severity'=>'high','campaignId'=>(int)$r['id'],'campaignCode'=>$r['CampaignCode'],'title'=>$r['TitleTh'],'message'=>!(int)$r['questionCount']?'ยังไม่มีคำถามหรือเนื้อหาสำหรับผู้เข้าร่วม':'ยังไม่ได้กำหนดกลุ่มผู้มีสิทธิ์','action'=>'workspace'];$sets=[['scheduled-soon','medium',"SELECT c.id,c.CampaignCode,v.TitleTh,c.ScheduledOpenAt dueAt FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.Status='Scheduled' AND c.ScheduledOpenAt BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 72 HOUR) ORDER BY c.ScheduledOpenAt LIMIT 20",'มีกำหนดเปิดภายใน 72 ชั่วโมง','operations'],['near-close','medium',"SELECT c.id,c.CampaignCode,v.TitleTh,c.ScheduledCloseAt dueAt FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.Status='Open' AND c.ScheduledCloseAt BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 72 HOUR) ORDER BY c.ScheduledCloseAt LIMIT 20",'ใกล้ปิดรับการเข้าร่วมภายใน 72 ชั่วโมง','operations'],['result-readiness','high',"SELECT c.id,c.CampaignCode,v.TitleTh,NULL dueAt FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID LEFT JOIN SafetyVote_ResultSnapshots rs ON rs.CampaignID=c.id AND rs.Status IN ('Ready','Certified','Published') WHERE c.Status='Closed' AND rs.id IS NULL ORDER BY c.ClosedAt LIMIT 20",'ปิดกิจกรรมแล้วและยังไม่มีผลที่พร้อมตรวจสอบ','results']];foreach($sets as[$key,$severity,$sql,$message,$action])foreach(db_rows($sql)as$r)$tasks[]=['key'=>$key,'severity'=>$severity,'campaignId'=>(int)$r['id'],'campaignCode'=>$r['CampaignCode'],'title'=>$r['TitleTh'],'message'=>$message,'dueAt'=>$r['dueAt']??null,'action'=>$action];foreach(db_rows("SELECT n.CampaignID id,c.CampaignCode,v.TitleTh,COUNT(*) failedCount FROM SafetyVote_Notifications n JOIN SafetyVote_Campaigns c ON c.id=n.CampaignID JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE n.Status='Failed' GROUP BY n.CampaignID,c.CampaignCode,v.TitleTh ORDER BY failedCount DESC LIMIT 20")as$r)$tasks[]=['key'=>'notification-failed','severity'=>'high','campaignId'=>(int)$r['id'],'campaignCode'=>$r['CampaignCode'],'title'=>$r['TitleTh'],'message'=>'การแจ้งเตือนส่งไม่สำเร็จ '.(int)$r['failedCount'].' รายการ','action'=>'operations'];$p=db_row("SELECT SUM(Status='Draft') drafts,SUM(Status='Published' AND StartAt<=NOW() AND EndAt>NOW()) live,SUM(Status='Published' AND StartAt>NOW()) scheduled FROM SafetyVote_Promotions")?:[];json_response(['success'=>true,'data'=>['tasks'=>array_slice($tasks,0,50),'summary'=>['total'=>count($tasks),'high'=>count(array_filter($tasks,fn($x)=>$x['severity']==='high')),'promotionDrafts'=>(int)($p['drafts']??0),'livePromotions'=>(int)($p['live']??0),'scheduledPromotions'=>(int)($p['scheduled']??0)],'privacySafe'=>true]]);}
 if($adminList&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$rows=db_rows('SELECT p.*,c.CampaignCode,c.Status CampaignStatus,v.TitleTh CampaignTitle,v.CampaignType FROM SafetyVote_Promotions p JOIN SafetyVote_Campaigns c ON c.id=p.CampaignID JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID ORDER BY p.Priority DESC,p.StartAt DESC,p.id DESC LIMIT 250');json_response(['success'=>true,'data'=>['rows'=>array_map('sveng_public',$rows)]]);}
 if($adminList&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$parsed=sveng_promotion(json_body());if(!$parsed['ok'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Promotion validation failed.','details'=>$parsed['errors']],400);$x=$parsed['value'];if(!db_row("SELECT id FROM SafetyVote_Campaigns WHERE id=? AND Status<>'Voided'",[$x['campaignId']]))json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);db_execute('INSERT INTO SafetyVote_Promotions(CampaignID,TitleTh,SubtitleTh,CtaLabel,DesktopFileID,MobileFileID,AltText,Priority,StartAt,EndAt,Status,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$x['campaignId'],$x['titleTh'],$x['subtitleTh'],$x['ctaLabel'],$x['desktopFileId'],$x['mobileFileId'],$x['altText'],$x['priority'],$x['startAt'],$x['endAt'],$x['status'],sv_actor($u),sv_actor($u)]);$id=(int)db()->lastInsertId();sv_audit($u,'SAFETY_VOTE_PROMOTION_CREATE','SafetyVote_Promotion',(string)$id,'status='.$x['status'],[],$x['campaignId']);json_response(['success'=>true,'data'=>sveng_public(sveng_row($id))],201);}
 if($adminItem&&$method==='PUT'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($adminItem['id']);$parsed=sveng_promotion(json_body());if(!$id||!$parsed['ok']||!$parsed['value']['rowVersion'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Promotion and rowVersion are required.','details'=>$parsed['errors']],400);$x=$parsed['value'];$pdo=db();$pdo->beginTransaction();try{$current=sveng_row($id,true);if(!$current){$pdo->rollBack();json_response(['success'=>false,'code'=>'PROMOTION_NOT_FOUND'],404);}if((int)$current['RowVersion']!==$x['rowVersion']){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_CONFLICT'],409);}$stmt=$pdo->prepare('UPDATE SafetyVote_Promotions SET CampaignID=?,TitleTh=?,SubtitleTh=?,CtaLabel=?,AltText=?,Priority=?,StartAt=?,EndAt=?,Status=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND RowVersion=?');$stmt->execute([$x['campaignId'],$x['titleTh'],$x['subtitleTh'],$x['ctaLabel'],$x['altText'],$x['priority'],$x['startAt'],$x['endAt'],$x['status'],sv_actor($u),$id,$x['rowVersion']]);if($stmt->rowCount()!==1){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_CONFLICT'],409);}$pdo->commit();sv_audit($u,'SAFETY_VOTE_PROMOTION_UPDATE','SafetyVote_Promotion',(string)$id,'status='.$x['status'],[],$x['campaignId']);json_response(['success'=>true,'data'=>sveng_public(sveng_row($id))]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'PROMOTION_UPDATE_FAILED'],500);}}
 if($asset&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($asset['id']);$slot=$asset['slot']==='desktop'?'DesktopFileID':($asset['slot']==='mobile'?'MobileFileID':null);$file=$_FILES['file']??null;if(!$id||!$slot||!$file||(int)$file['error']!==UPLOAD_ERR_OK||(int)$file['size']>10*1024*1024)json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED'],400);$mime=sv_file_mime((string)$file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED'],400);$ext=['image/jpeg'=>'.jpg','image/png'=>'.png','image/webp'=>'.webp'][$mime];$stored=time().'-'.bin2hex(random_bytes(18)).$ext;$target=sv_private_dir().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file((string)$file['tmp_name'],$target))json_response(['success'=>false,'code'=>'FILE_UPLOAD_REJECTED'],500);$pdo=db();$pdo->beginTransaction();try{$p=sveng_row($id,true);if(!$p){$pdo->rollBack();sveng_remove_file($stored);json_response(['success'=>false,'code'=>'PROMOTION_NOT_FOUND'],404);}$purpose=$slot==='MobileFileID'?'promotion_mobile':'promotion_desktop';$stmt=$pdo->prepare('INSERT INTO SafetyVote_Files(CampaignID,CampaignVersionID,FilePurpose,StoredName,OriginalName,MimeType,FileSize,ContentSha256,UploadedBy) VALUES(?,?,?,?,?,?,?,?,?)');$stmt->execute([(int)$p['CampaignID'],(int)$p['CurrentVersionID'],$purpose,$stored,sv_clean($file['name']??'',255),$mime,(int)$file['size'],hash_file('sha256',$target),sv_actor($u)]);$fileId=(int)$pdo->lastInsertId();$oldId=!empty($p[$slot])?(int)$p[$slot]:null;$pdo->prepare("UPDATE SafetyVote_Promotions SET $slot=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([$fileId,sv_actor($u),$id]);$old=$oldId?db_row('SELECT StoredName FROM SafetyVote_Files WHERE id=?',[$oldId]):null;if($oldId)$pdo->prepare("UPDATE SafetyVote_Files SET Status='Removed',RemovedAt=NOW(),RemovedBy=? WHERE id=?")->execute([sv_actor($u),$oldId]);$pdo->commit();if($old)sveng_remove_file($old['StoredName']);sv_audit($u,'SAFETY_VOTE_PROMOTION_ASSET_REPLACE','SafetyVote_Promotion',(string)$id,'slot='.$slot,['fileId'=>$fileId],(int)$p['CampaignID']);json_response(['success'=>true,'data'=>sveng_public(sveng_row($id))],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();sveng_remove_file($stored);json_response(['success'=>false,'code'=>'PROMOTION_ASSET_FAILED'],500);}}
 if($promotions&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_VIEW');$rows=db_rows("SELECT DISTINCT p.*,c.CampaignCode,c.Status CampaignStatus,v.TitleTh CampaignTitle,v.CampaignType FROM SafetyVote_Promotions p JOIN SafetyVote_Campaigns c ON c.id=p.CampaignID JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID JOIN SafetyVote_EligibilitySnapshots s ON s.CampaignVersionID=c.CurrentVersionID AND s.Status='frozen' JOIN SafetyVote_EligibleVoters ev ON ev.SnapshotID=s.id AND ev.EmployeeID=? WHERE p.Status='Published' AND p.StartAt<=NOW() AND p.EndAt>NOW() AND c.Status IN ('Scheduled','Open','Closed','Certified','Published') ORDER BY p.Priority DESC,p.StartAt DESC,p.id DESC LIMIT 10",[sv_actor($u)]);json_response(['success'=>true,'data'=>['rows'=>array_map('sveng_public',$rows)]]);}
 if($center&&$method==='GET'){sv_require_permission($u,'SAFETY_VOTE_VIEW');$rows=db_rows("SELECT n.id,n.CampaignID,n.EventType,n.TemplateKey,n.Channel,n.DispatchedAt,n.PayloadMetadataJson,r.ReadAt,c.CampaignCode,v.TitleTh CampaignTitle FROM SafetyVote_Notifications n JOIN SafetyVote_Campaigns c ON c.id=n.CampaignID JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID LEFT JOIN SafetyVote_NotificationReads r ON r.NotificationID=n.id AND r.EmployeeID=? WHERE n.RecipientEmployeeID=? AND n.Status='Sent' ORDER BY n.DispatchedAt DESC,n.id DESC LIMIT 100",[sv_actor($u),sv_actor($u)]);foreach($rows as&$r){$r=['id'=>(int)$r['id'],'campaignId'=>(int)$r['CampaignID'],'campaignCode'=>$r['CampaignCode'],'campaignTitle'=>$r['CampaignTitle'],'eventType'=>$r['EventType'],'templateKey'=>$r['TemplateKey'],'channel'=>$r['Channel'],'dispatchedAt'=>$r['DispatchedAt'],'readAt'=>$r['ReadAt'],'metadata'=>json_decode((string)$r['PayloadMetadataJson'],true)?:[]];}unset($r);json_response(['success'=>true,'data'=>['rows'=>$rows]]);}
 if($read&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_VIEW');$id=sv_positive_int($read['id']);if(!$id||!db_row("SELECT id FROM SafetyVote_Notifications WHERE id=? AND RecipientEmployeeID=? AND Status='Sent'",[$id,sv_actor($u)]))json_response(['success'=>false,'code'=>'NOTIFICATION_NOT_FOUND'],404);db_execute('INSERT INTO SafetyVote_NotificationReads(NotificationID,EmployeeID) VALUES(?,?) ON DUPLICATE KEY UPDATE ReadAt=ReadAt',[$id,sv_actor($u)]);json_response(['success'=>true,'data'=>['id'=>$id,'read'=>true]]);}
 if($readAll&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_VIEW');$stmt=db()->prepare("INSERT IGNORE INTO SafetyVote_NotificationReads(NotificationID,EmployeeID) SELECT id,? FROM SafetyVote_Notifications WHERE RecipientEmployeeID=? AND Status='Sent'");$stmt->execute([sv_actor($u),sv_actor($u)]);json_response(['success'=>true,'data'=>['marked'=>$stmt->rowCount()]]);}
 return false;
}
